export const createRateVersionBodyCodeRegExp = new RegExp("^[a-z0-9-]{2,40}$");
export const createRateVersionBodyNameMin = 2;
export const createRateVersionBodyNameMax = 80;

export const createRateVersionBodyDescriptionMax = 300;

export const createRateVersionBodyBaseFeeCentsMin = 0;

export const createRateVersionBodyPerKgCentsMin = 0;

export const createRateVersionBodyFuelPctMin = 0;
export const createRateVersionBodyFuelPctMax = 100;

export const createRateVersionBodyMinWeightKgExclusiveMin = 0;

export const createRateVersionBodyMaxWeightKgExclusiveMin = 0;

export const createRateVersionBodyTransitDaysMinMin = 0;

export const createRateVersionBodyTransitDaysMaxMin = 0;

export const CreateRateVersionBody = zod.object({
  code: zod.string().regex(createRateVersionBodyCodeRegExp),
  name: zod
    .string()
    .min(createRateVersionBodyNameMin)
    .max(createRateVersionBodyNameMax),
  description: zod.string().max(createRateVersionBodyDescriptionMax),
  baseFeeCents: zod.number().min(createRateVersionBodyBaseFeeCentsMin),
  perKgCents: zod.number().min(createRateVersionBodyPerKgCentsMin),
  fuelPct: zod
    .number()
    .min(createRateVersionBodyFuelPctMin)
    .max(createRateVersionBodyFuelPctMax),
  minWeightKg: zod.number().gt(createRateVersionBodyMinWeightKgExclusiveMin),
  maxWeightKg: zod.number().gt(createRateVersionBodyMaxWeightKgExclusiveMin),
  transitDaysMin: zod.number().min(createRateVersionBodyTransitDaysMinMin),
  transitDaysMax: zod.number().min(createRateVersionBodyTransitDaysMaxMin),
});

